/**
 * /search.json — the whole diary index as one small JSON file (plan A: no search server,
 * no extra dependency). Regenerated by every Eleventy build; the search box on the home
 * page and on each category page fetches it once and filters in the browser.
 *
 * Shape:
 *   { generated, count, posts: [{ title, summary, category, categoryLabel, categorySlug,
 *                                 tags, date, dateLabel, url, keywords }] }
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { extractKeywords, normalizeTags } from "./lib/search-index.js";
import { displayDate, htmlDate } from "./lib/utils.js";

const sourceRoot = fileURLToPath(new URL("./", import.meta.url));

function keywordsFor(inputPath) {
  if (!inputPath) return "";
  const relative = String(inputPath).replace(/^\.\//, "");
  try {
    return extractKeywords(readFileSync(join(sourceRoot, relative), "utf8"));
  } catch {
    return "";
  }
}

export default class SearchIndex {
  data() {
    return {
      permalink: "/search.json",
      eleventyExcludeFromCollections: true,
    };
  }

  render({ collections }) {
    const posts = (collections?.diaryPosts ?? []).map((post) => ({
      title: post.data.title ?? "",
      summary: post.data.summary ?? "",
      category: post.data.category ?? "",
      categoryLabel: post.data.categoryName ?? post.data.category ?? "",
      categorySlug: post.data.categorySlug ?? "",
      tags: normalizeTags(post.data.tags),
      date: htmlDate(post.date),
      dateLabel: displayDate(post.date),
      url: post.url,
      keywords: keywordsFor(post.page?.inputPath),
    }));

    return JSON.stringify({
      generated: new Date().toISOString(),
      count: posts.length,
      posts,
    });
  }
}
